#include <iostream>

using namespace std;

int main() {
    int N, K;
    cin >> N >> K;

    // はじめ、空席は K 個、スタートした回数は 0 回
    int empty_sheets = K, start_count = 0;

    for (int i = 0; i < N; ++i) {
        int a;
        cin >> a; // 人数を入力
        if (empty_sheets < a) { // 空席が足りなければ
            ++start_count; // スタートして
            empty_sheets = K; // 空席を K 個に
        }
        empty_sheets -= a; // a 人座る
    }
    ++start_count; // 最後に 1 回スタートする

    cout << start_count << endl;

    return 0;
}
